SELECT h.hk_customer AS customer_hk, h.customer_key, s.customer_name, s.email, s.phone, bv.full_address, s.city, s.state_province, s.postal_code, s.country_code, s.customer_segment, bv.customer_type, bv.tenure_band, bv.is_contactable, s.customer_since, s.is_deleted, s.load_date AS valid_from, coalesce(s.load_end_date, timestamp'9999-12-31 23:59:59') AS valid_to, s.is_current, s.record_source FROM {processing}.raw_vault.hub_customer h JOIN {processing}.raw_vault.sat_customer s ON s.hk_customer = h.hk_customer LEFT JOIN {processing}.business_vault.sat_customer_bv bv ON bv.hk_customer = h.hk_customer AND s.load_date >= bv.load_date AND s.load_date < coalesce(bv.load_end_date, timestamp'9999-12-31 23:59:59')
